                rn[0] = pref * fm[0];
                let m2a = alpha * V::splat(-2.0);
                let mut f = pref;
                f *= m2a;
                rn[1] = f * fm[1];
                f *= m2a;
                rn[2] = f * fm[2];
                f *= m2a;
                rn[3] = f * fm[3];
                f *= m2a;
                rn[4] = f * fm[4];
