/// (20|00) for one bra pair and 8 ket pairs (lanes): out[ab * 1 + cd].
/// p, pc: bra primitives; eb: bra E nonzeros (24 per primitive); lane: ket records
/// (6 lane vectors per ket primitive). Fixed-size views keep the body free of bounds checks.
#[inline(always)]
#[allow(unused_variables, unused_mut)]
pub fn block_20_00<V: Lanes>(p: &[f64], pc: &[[f64; 3]], eb: &[f64], lane: &[[f64; 8]], nk: usize, op: &Operator, qpb: &[f64], qpk: &[f64], cut: f64, out: &mut [V]) {
    let coulomb = op.is_coulomb();
    const NREC: usize = 6;
    const NNZB: usize = 24;
    let mut acc = [V::zero(); 5];
    let mut fm = [V::zero(); 3];
    let mut rn = [V::zero(); 3];
    let mut r = [V::zero(); 10];
    let pc = &pc[..p.len()];
    let qpb = &qpb[..p.len()];
    let qpk = &qpk[..nk];
    let btab = boys_table();
    for ip in 0..p.len() {
        let (pp, [px, py, pz]) = (p[ip], pc[ip]);
        let vp = V::splat(pp);
        let pref0 = V::splat(ERI_PREF / pp);
        let qb = qpb[ip];
        let mut t = [V::zero(); 10];
        for kq in 0..nk {
            if qb * qpk[kq] < cut {
                continue;
            }
            let kd: &[[f64; 8]; NREC] = lane[kq * NREC..(kq + 1) * NREC].try_into().unwrap();
            let q = V::load8(&kd[0]);
            let inv_q = V::load8(&kd[1]);
            let dx = V::splat(px) - V::load8(&kd[2]);
            let dy = V::splat(py) - V::load8(&kd[3]);
            let dz = V::splat(pz) - V::load8(&kd[4]);
            let inv_s = V::splat(1.0) / (vp + q);
            let alpha = vp * q * inv_s;
            let r2 = dx.mul_add(dx, dy.mul_add(dy, dz * dz));
            let pref = pref0 * inv_q * inv_s.sqrt();
            if coulomb {
                boys_lanes_tab(btab, 2, alpha * r2, &mut fm);
                rn[0] = pref * fm[0];
                let m2a = alpha * V::splat(-2.0);
                let mut f = pref;
                f *= m2a;
                rn[1] = f * fm[1];
                f *= m2a;
                rn[2] = f * fm[2];
            } else {
                rn_operator(2, alpha, r2, pref, op, &mut fm, &mut rn);
            }
            r_tensor_2(&rn, dx, dy, dz, &mut r);
            let e0 = V::load8(&kd[5]);
            t[0] = r[0].mul_add(e0, t[0]);
            t[1] = r[1].mul_add(e0, t[1]);
            t[2] = r[2].mul_add(e0, t[2]);
            t[3] = r[3].mul_add(e0, t[3]);
            t[4] = r[4].mul_add(e0, t[4]);
            t[5] = r[5].mul_add(e0, t[5]);
            t[6] = r[6].mul_add(e0, t[6]);
            t[7] = r[7].mul_add(e0, t[7]);
            t[8] = r[8].mul_add(e0, t[8]);
            t[9] = r[9].mul_add(e0, t[9]);
        }
        let eb: &[f64; NNZB] = eb[ip * NNZB..(ip + 1) * NNZB].try_into().unwrap();
        let b0 = V::splat(eb[0]);
        let b1 = V::splat(eb[1]);
        let b2 = V::splat(eb[2]);
        let b3 = V::splat(eb[3]);
        let b4 = V::splat(eb[4]);
        let b5 = V::splat(eb[5]);
        let b6 = V::splat(eb[6]);
        let b7 = V::splat(eb[7]);
        let b8 = V::splat(eb[8]);
        let b9 = V::splat(eb[9]);
        let b10 = V::splat(eb[10]);
        let b11 = V::splat(eb[11]);
        let b12 = V::splat(eb[12]);
        let b13 = V::splat(eb[13]);
        let b14 = V::splat(eb[14]);
        let b15 = V::splat(eb[15]);
        let b16 = V::splat(eb[16]);
        let b17 = V::splat(eb[17]);
        let b18 = V::splat(eb[18]);
        let b19 = V::splat(eb[19]);
        let b20 = V::splat(eb[20]);
        let b21 = V::splat(eb[21]);
        let b22 = V::splat(eb[22]);
        let b23 = V::splat(eb[23]);
        acc[0] = b18.mul_add(t[5], b9.mul_add(t[2], b5.mul_add(t[1], b0.mul_add(t[0], acc[0]))));
        acc[1] = b22.mul_add(t[8], b13.mul_add(t[3], b10.mul_add(t[2], b1.mul_add(t[0], acc[1]))));
        acc[2] = b23.mul_add(t[9], b20.mul_add(t[7], b16.mul_add(t[4], b14.mul_add(t[3], b11.mul_add(t[2], b6.mul_add(t[1], b2.mul_add(t[0], acc[2])))))));
        acc[3] = b19.mul_add(t[6], b15.mul_add(t[3], b7.mul_add(t[1], b3.mul_add(t[0], acc[3]))));
        acc[4] = b21.mul_add(t[7], b17.mul_add(t[4], b12.mul_add(t[2], b8.mul_add(t[1], b4.mul_add(t[0], acc[4])))));
    }
    out[..5].copy_from_slice(&acc);
}

