                rn[1] = f * fm[1];
                f *= m2a;
                rn[2] = f * fm[2];
                f *= m2a;
                rn[3] = f * fm[3];
                f *= m2a;
                rn[4] = f * fm[4];
                f *= m2a;
                rn[5] = f * fm[5];
                f *= m2a;
